//! Every function the crate declares (for the enabled feature set) resolves in the installed AOCL-BLIS (dynamic build: taking the
//! address forces the link). The list is generated by build.rs from the bindings actually generated. MEASURED on AOCL 6.0.68
//! Windows (LP64 and ILP64; Linux unmeasured). With `static-link` the static BLIS also needs the OpenMP runtime on the link line
//! (not linked by this crate), so this test is for the dynamic build; with `header-only-unexported` it fails to link on Windows
//! by design (those names exist nowhere).
#![cfg(not(feature = "static-link"))]
#![allow(warnings)]

#[test]
fn declared_symbols_link() {
    let addrs: Vec<usize> = include!(concat!(env!("OUT_DIR"), "/link_all_list.rs"));
    if !cfg!(feature = "header-only-unexported") {
        let expected = 3228
            + if cfg!(feature = "libflame") { 1 } else { 0 }
            + if cfg!(feature = "scalapack-fal") {
                13
            } else {
                0
            };
        assert_eq!(addrs.len(), expected);
    }
    assert!(addrs.iter().all(|a| *a != 0));
}
